    ctx.lineTo(x + pw, y + ph - ch);
    ctx.lineTo(x + pw - ch, y + ph);
    ctx.lineTo(x + ch, y + ph);
    ctx.lineTo(x, y + ph - ch);
    ctx.lineTo(x, y + ch);
