  drawSteelPath(pad, pad, w - pad * 2, h - pad * 2, chamfer);
  ctx.fill();
  ctx.strokeStyle = "rgba(255, 255, 255, 0.85)";
  ctx.lineWidth = 3;
  drawSteelPath(pad + 1, pad + 1, w - pad * 2 - 2, h - pad * 2 - 2, chamfer);
